# === BPL Quick Reference ===

# Variables
local x: int = 42;          # Mutable
local const PI: float = 3.14; # Immutable
global count: int = 0;      # Global variable

# Functions (called 'frames')
frame add(a: int, b: int) ret int {
    return a + b;
}

# Structs with methods
struct Point {
    x: int, y: int,
    frame new(x: int, y: int) ret Point { return Point { x: x, y: y }; }
}

# Enums (algebraic data types)
enum Option<T> { Some(T), None }

# Pattern matching
match (opt) {
    Option.Some(val) => { /* use val */ },
    Option.None => { /* handle none */ },
}

# Error handling
try {
    throw 1;
} catch (e: int) {
    /* handle error */
}

# Lambdas
local square: Lambda<int>(int) = |x: int| ret int { return x * x; };

# Memory management
local ptr: *int = cast<*int>(malloc(sizeof<int>()));
defer { free(cast<*void>(ptr)); }

# FFI
extern printf(fmt: string, ...);
